//! Places where Excel differs from CLDR (ADR-011).
//!
//! Every entry here is backed by a measurement or is a documented policy:
//!
//! * [`NAME_OVERRIDES`] holds month, day and AM/PM names. Each entry is a measured Excel output,
//!   recorded by `tools/office/locale-oracle.ps1` into `fixtures/reference/locale/excel-names.json`
//!   (Excel `TEXT()` with a `[$-LCID]` prefix; no regional setting was changed). An entry exists only
//!   where Excel's list differs from CLDR's, and the `names_match_excel` test fails if the table is
//!   stale. Regenerate with `cargo test -p open365-locale --test excel_names regenerate -- --ignored`.
//! * [`normalize_minus`] and [`list_separator`] are policies that cannot be measured without changing
//!   the machine's regional settings (ADR-011 keeps that to a separate profile or VM); see each function.
//!
//! Measured facts that shape the API:
//!
//! * Excel never uses genitive month names: `d mmmm` equals `mmmm` in every locale (all 418 LCIDs).
//! * Excel abbreviates differently from CLDR (`Mrz` not `Mär`, no trailing period, `So` not `So.`).
//! * LCIDs 0x0001 (`ar`), 0x0002 (`bg`) and 0x0471 (`kr-Latn-NG`) are not locales Excel can use as
//!   `[$-LCID]`: it answers with the en-US names, so no override is recorded for them.

use crate::Locale;
use crate::datetime::CalendarNames;

/// Which names list an override replaces.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub enum NameField {
    /// Twelve full month names (`mmmm`).
    MonthFull,
    /// Twelve abbreviated month names (`mmm`).
    MonthAbbr,
    /// Seven full day names, Sunday first (`dddd`).
    DayFull,
    /// Seven abbreviated day names, Sunday first (`ddd`).
    DayAbbr,
    /// Two entries: AM then PM (`AM/PM`).
    AmPm,
}

/// One measured replacement of a whole names list for an LCID.
#[derive(Clone, Copy, Debug)]
pub struct NameOverride {
    pub lcid: u32,
    pub field: NameField,
    pub values: &'static [&'static str],
}

/// Looks up the override for an LCID and field.
pub fn name_override(lcid: u32, field: NameField) -> Option<&'static NameOverride> {
    NAME_OVERRIDES
        .binary_search_by(|o| (o.lcid, o.field).cmp(&(lcid, field)))
        .ok()
        .map(|i| &NAME_OVERRIDES[i])
}

fn replace(target: &mut [String], over: Option<&NameOverride>) {
    if let Some(over) = over
        && over.values.len() == target.len()
    {
        for (slot, value) in target.iter_mut().zip(over.values) {
            (*value).clone_into(slot);
        }
    }
}

pub(crate) fn apply_names(lcid: u32, names: &mut CalendarNames) {
    replace(
        &mut names.month_full,
        name_override(lcid, NameField::MonthFull),
    );
    replace(
        &mut names.month_abbr,
        name_override(lcid, NameField::MonthAbbr),
    );
    replace(&mut names.day_full, name_override(lcid, NameField::DayFull));
    replace(&mut names.day_abbr, name_override(lcid, NameField::DayAbbr));
    if let Some(over) = name_override(lcid, NameField::AmPm)
        && let [am, pm] = over.values
    {
        (*am).clone_into(&mut names.am);
        (*pm).clone_into(&mut names.pm);
    }
}

/// Policy: Excel writes the minus sign as ASCII `-` (CLDR uses U+2212 in sv, fi, nb, hr, sl and others).
/// Not measured; to be confirmed by the per-culture oracle profile.
pub(crate) fn normalize_minus(text: &str) -> String {
    text.replace('\u{2212}', "-")
}

/// Policy: the argument separator typed in formulas is `;` where the decimal separator is `,` (or
/// the Arabic decimal separator), else `,`. This is the Windows default pairing for the
/// list-separator setting. Not measured (`Application.International` only reports the machine's own
/// setting); to be confirmed by the per-culture oracle profile.
pub(crate) fn list_separator(_locale: &Locale, decimal_separator: &str) -> String {
    if decimal_separator == "," || decimal_separator == "\u{66b}" {
        ";".to_owned()
    } else {
        ",".to_owned()
    }
}

